#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    string s;
    cin >> s;

    vector<pair<string, int>> stack;
    string cur;
    int num = 0;
    for (char ch : s) {
        if (ch >= '0' && ch <= '9') {
            num = num * 10 + (ch - '0');
        } else if (ch == '[') {
            stack.push_back({cur, num});
            cur = "";
            num = 0;
        } else if (ch == ']') {
            string prev = stack.back().first;
            int k = stack.back().second;
            stack.pop_back();
            for (int i = 0; i < k; i++) prev += cur;
            cur = prev;
        } else {
            cur += ch;
        }
    }
    cout << cur << "\n";

    return 0;
}

